	//if (damage - mpEquipmentManager->GetDamage() <= 0) { hp_ -= 1; return; }//鬯ｯ・ｮ・ｽ・ｫ郢晢ｽｻ・ｽ・ｴ鬮ｯ譎｢・ｽ・ｷ驛｢譎｢・ｽ・ｻ髯ｷ謇假ｽｽ・ｲ鬯ｮ・ｯ雋頑瑳・ｱ螢ｹ・ｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｱ鬯ｩ謳ｾ・ｽ・ｵ郢晢ｽｻ・ｽ・ｲ鬮ｯ諛ｶ・ｽ・｣郢晢ｽｻ・ｽ・､驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｹ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｧ鬯ｩ蟷｢・ｽ・｢郢晢ｽｻ・ｽ・ｧ鬯ｮ・｣鬲・ｼ夲ｽｽ・ｽ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｸ鬯ｮ・ｯ隴趣ｽ｢・ｽ・ｽ・ｽ・ｶ鬮ｯ・ｷ・ｽ・ｻ郢晢ｽｻ・ｽ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ鬯ｮ・｢・ｽ・ｾ郢晢ｽｻ・ｽ・･驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｸ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｺ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ
	if (now == ANIMATION_SLIDE || now == ANIMATION_ATTACKSLIDE)return;
	hp_ -= (damage-mpEquipmentManager->GetDamage());//鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｬ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｩ隰ｳ・ｾ・ｽ・ｽ・ｽ・ｵ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｺ鬯ｮ・ｯ・ｽ・ｷ髣費ｽｨ陞滂ｽｲ・ｽ・ｽ・ｽ・ｽ郢晢ｽｻ・ｽ・ｱ鬯ｩ蛹・ｽｽ・ｯ郢晢ｽｻ・ｽ・ｶ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｻ鬯ｯ・ｩ隰ｳ・ｾ・ｽ・ｽ・ｽ・ｵ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｺ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ隲�・ｹ・ｽ・ｼ陞滂ｽｲ・ｽ・ｽ・ｽ・ｽ郢晢ｽｻ・ｽ・ｹ鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・｡鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｼ鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｧE鬯ｯ・ｮ・ｽ・ｯ髯ｷ闌ｨ・ｽ・ｷ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｿ郢晢ｽｻ・ｽ・ｽ鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・｡鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｼ鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｧE鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｧ鬯ｮ・ｯ・ｽ・ｷ郢晢ｽｻ・ｽ・ｻ鬯ｮ・｣鬲・ｼ夲ｽｽ・ｽ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｸ鬯ｮ・ｯ隴趣ｽ｢・ｽ・ｽ・ｽ・ｶ鬮ｯ・ｷ・ｽ・ｻ郢晢ｽｻ・ｽ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ鬯ｮ・｢・ｽ・ｾ郢晢ｽｻ・ｽ・･驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｸ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｺ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ

