void Player3D::OnEnter(Collider* collider, Collider* check)
{
	

	if (collider == mpSerchEnemyCollider && check->parent_object_->GetTag() == Object3D::Tag3D_Enemy3D)
	{
		

		auto pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		VECTOR mnEneDistance = VSub(pEne->GetPosition(), position_);
		if (check == pEne->GetEnemycoll())
		{
			mbAttackSlideSerch = true;
			float VECSize = VSize(mnEneDistance);
			FirstNearVec++;
			if (FirstNearVec == 1)
			{
				VECSizeFirst = VECSize;
			}

			if (VECSizeFirst <= VECSize)
			{
				VECSizeFirst = VECSize;
				target_ = pEne;

			}
		}
	}


	if (collider == mpCapsuleCollider && check->parent_object_->GetTag() == Tag3D_Obj)
	{
		position_ = old_position_;//object邵ｺ・ｫ陟冶侭笳・ｸｺ・｣邵ｺ貅假ｽ臥ｸｺ・ｲ邵ｺ・ｨ邵ｺ・､陷鷹亂竊楢ｬ鯉ｽｻ郢ｧ
	}

}

void Player3D::OnTrigger(Collider* collider, Collider* check)
{

	AnimationState now = model_->GetNowState();

	if (now == ANIMATION_ATTACK)
	{
		if (collider == mpAttachCollider && check->parent_object_->GetTag() == Object3D::Tag3D_Enemy3D)
		{
			Enemy* pEne = check->parent_object_->CastTo<Enemy>();
			if (pEne == nullptr) return;
			if (check == pEne->GetEnemycoll())
			{
				
				// 鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫEE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫEE鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢EEE鬯ｯ・ｨ・ｽ・ｾ郢晢ｽｻ・ｽ・ｧEE鬯ｮ・ｫ・ｽ・ｴ鬮ｮ諛ｶ・ｽ・｣郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢EE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢鬯ｮ・ｫ・ｽ・ｴ鬮ｮ諛ｶ・ｽ・｣郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢EE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢鬯ｮ・ｫ・ｽ・ｴ鬮ｮ諛ｶ・ｽ・｣郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢EE&&Attack1
				if (now == ANIMATION_ATTACK && AttackState == Attack_Normal && !mbjump && !pEne->GetHitjudgment())
				{
					
					pEne->Damage(GetAllStatusState(Object3D::Status_Attack));
					// 鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｨE鬯ｮ・ｯ陷茨ｽｷ・ｽ・ｽ・ｽ・ｹ鬩幢ｽ｢隴趣ｽ｢・ｽ・ｽ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｯEE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫEE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｯ・ｮ・ｽ・ｯ髮矩｡板ｧ隰ｫE鬮｣雋ｻ・ｽ・ｨ髯樊ｻゑｽｽ・ｲ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｽE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE鬯ｯ・ｮ・ｽ・ｯ髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｶ鬯ｮ・ｯ・ｽ・ｷ郢晢ｽｻ・ｽ・ｻEE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ
					Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
					EffectPool::GetInstance()->Play(VAdd(pEne->GetPosition(), VGet(0.0f, 60.0f, 0.0f)), "Resource/2d/Damage.png", GetColorU8(255, 0, 30, 0), 30.0f, 0.1f);
				}


			}

		}
	}
	if (collider == mpAttackJumpCollider && check->parent_object_->GetTag() == Tag3D_Enemy3D)
	{
		Enemy* pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		if (check == pEne->GetEnemycoll())
		{
			if (now == ANIMATION_ATTACKJUMP && AttackState == Attack_Jump && !pEne->GetHitjudgment())
			{
				pEne->SetHitjudgment(true);
				pEne->Damage(GetAllStatusState(Object3D::Status_Attack) + mfAttackjump);

				// 鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｾ鬯ｮ・ｯ陷茨ｽｷ・ｽ・ｽ・ｽ・ｹ鬩幢ｽ｢隴趣ｽ｢・ｽ・ｽ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｯ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｮE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｰE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｯ・ｮ・ｽ・ｯ髮矩｡板ｧ隰ｫ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｯ鬮｣雋ｻ・ｽ・ｨ髯樊ｻゑｽｽ・ｲ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｼ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE鬯ｯ・ｮ・ｽ・ｯ髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｶ鬯ｮ・ｯ・ｽ・ｷ郢晢ｽｻ・ｽ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｻE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ
				Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
				EffectPool::GetInstance()->Play(VAdd(pEne->GetPosition(), VGet(0.0f, 60.0f, 0.0f)), "Resource/2d/Damage.png", GetColorU8(255, 100, 0, 0), 45.0f, 0.5f);
			}
		}
	}

	if (collider == mpAttackSlideCollider && check->parent_object_->GetTag() == Tag3D_Enemy3D)
	{
		Enemy* pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		if (check == pEne->GetEnemycoll())
		{
			if (now == ANIMATION_ATTACKSLIDE && AttackState == Attack_Slide && !pEne->GetHitjudgment())
			{
				pEne->Damage(GetAllStatusState(Object3D::Status_Attack) + mfAttackSlide);
				pEne->SetHitjudgment(true);
				// 鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｾ鬯ｮ・ｯ陷茨ｽｷ・ｽ・ｽ・ｽ・ｹ鬩幢ｽ｢隴趣ｽ｢・ｽ・ｽ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｯ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｮE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｰE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｩ髯晢ｽｷ・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｯ・ｮ・ｽ・ｯ髮矩｡板ｧ隰ｫ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｯ鬮｣雋ｻ・ｽ・ｨ髯樊ｻゑｽｽ・ｲ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｼ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE鬯ｯ・ｮ・ｽ・ｯ髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｶ鬯ｮ・ｯ・ｽ・ｷ郢晢ｽｻ・ｽ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｻE鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ
				Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
				EffectPool::GetInstance()->Play(VAdd(pEne->GetPosition(), VGet(0.0f, 60.0f, 0.0f)), "Resource/2d/Damage.png", GetColorU8(35, 0, 255, 0), 60.0f, 1.0f);
			}
		}
	}
	


}
void Player3D::mpTargetOn()
{
	if (target_ != nullptr)
	{
		bool isTargetValid = false;
		const auto& mpEneList = Master::mpSceneManager->GetCurrentScene()->GetObjectManager()->GetObject3DListByTag(Object3D::Tag3D_Enemy3D);
		for (int i = 0; i < mpEneList.size(); i++)
		{
			if (target_ == mpEneList.at(i) && !target_->IsDeleteFlag())
			{
				isTargetValid = true;
				break;
			}
		}
		if (!isTargetValid)
		{
			target_ = nullptr;
		}
	}
}

