void Player3D::SelectAttack()
{
	AttackCountClass();
	AnimationState now = model_->GetNowState();
	if (InputManager::CheckDownKey(KEY_INPUT_E) && now != ANIMATION_ATTACK)
	{
		ChangeStateCount++;
		if (ChangeStateCount > 2)
		{
			ChangeStateCount = 0;
		}

	}

	switch (ChangeStateCount)
	{
	case 0:

		AttackState = Attack_Normal;
		Attack();
		break;
	case 1:

		AttackState = Attack_Slide;
		AttackSlide();
		break;
	case 2:
		AttackState = Attack_Jump;
		AttackJump();
	default:
		break;
	}
	if (Master::mpDebug)
	{
		DrawFormatString(300, 300, GetColor(255, 255, 255), "%d", ChangeStateCount);
	}
	if (!(now==ANIMATION_ATTACK)&& !(now == ANIMATION_ATTACKJUMP)&& !(now == ANIMATION_ATTACKSLIDE))//鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ鬮ｫ・ｶ陷ｻ・ｻ・ｽ・ｽ・ｽ・ｸ鬯ｮ・｣隲橸ｽｺ陞ｻ・ｮ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｭ鬯ｯ・ｮ・ｽ・ｫ郢晢ｽｻ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｳ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｮ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｮ鬯ｩ蛹・ｽｽ・ｶ髫ｰ・ｫ・ｽ・ｾ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｵ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ鬮ｫ・ｶ陷ｴ・ｽ・ｽ・ｽ・ｸ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｳ鬯ｯ・ｮ・ｽ・ｯ髫ｶ蜴・ｽｽ・ｸ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｯ・ｩ陝ｷ・｢・ｽ・ｽ・ｽ・｢鬮ｫ・ｴ髮懶ｽ｣・ｽ・ｽ・ｽ・｢驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｻ鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ鬮ｮ荵晢ｽｻ・ｽ・ｽ・ｽ・ｷ鬮ｫ・ｴ・ｽ・ｯ驛｢譎｢・ｽ・ｻE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｮ鬯ｮ・ｮ隲幢ｽｶ・ｽ・ｽ・ｽ・｣驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・｢鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻE
	{
		const auto& mpEne = Master::mpSceneManager->GetCurrentScene()->GetObjectManager()->GetObject3DListByTag(Object3D::Tag3D_Enemy3D);
		for (int i = 0; i < mpEne.size(); i++)
		{
			Enemy* pEne = mpEne.at(i)->CastTo<Enemy>();
			if (pEne == nullptr) continue;
			pEne->SetHitjudgment(false);
		}
	}

}

void Player3D::AttackCountClass()
{


	AttackCount++;
	AttackSlideCount++;
	AttackJumpCount++;


}
void Player3D::CollPositionUpdate()
{
	AnimationState now = model_->GetNowState();
	// 鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ鬮ｫ・ｶ陷ｻ・ｻ・ｽ・ｽ・ｽ・ｸ鬯ｮ・｣隲橸ｽｺ陞ｻ・ｮ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｭ鬯ｯ・ｮ・ｽ・ｫ郢晢ｽｻ・ｽ・ｨ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｳ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE鬯ｯ・ｯ・ｽ・ｯ郢晢ｽｻ・ｽ・ｮ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｮ鬯ｩ蛹・ｽｽ・ｶ髫ｰ・ｫ・ｽ・ｾ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｵ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻ鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｯ鬮ｫ・ｶ陷ｴ・ｽ・ｽ・ｽ・ｸ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｽ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｳ鬯ｯ・ｮ・ｽ・ｯ髫ｶ蜴・ｽｽ・ｸ郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・｢E鬯ｯ・ｮ・ｽ・ｯ髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｲE鬯ｯ・ｯ・ｽ・ｮ郢晢ｽｻ・ｽ・ｫ驛｢譎｢・ｽ・ｻ郢晢ｽｻ・ｽ・ｴ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ・ｽ・ｽ郢晢ｽｻ・ｽ・ｻEE
	mpCapsuleCollider->position_ = position_;
	mpCapsuleCollider->position2_ = VAdd(position_, VGet(0.0f, 150.0f, 0.0f));

	mpAttachCollider->position_ = VGet(1000, 10000, 1000);
	mpSerchEnemyCollider->position_ = position_;
	mpAttackSlideCollider->position_ = VGet(1000, 10000, 1000);
	mpAttackJumpCollider->position_ = VGet(1000, 10000, 1000);
	if (now == ANIMATION_ATTACKSLIDE && AttackState == Attack_Slide)
	{
		mpAttackSlideCollider->position_ = position_;
	}
	else if (now == ANIMATION_ATTACKJUMP && AttackState == Attack_Jump&& OnJumpCollider)
	{
		mpAttackJumpCollider->position_ = position_;
	}
	else if (now == ANIMATION_ATTACK)
	{
		mpAttachCollider->position_ = model_->GetAttachmentPosition();
	}

}

float Player3D::GetAllStatusState(Object3D::StatusState state)
{
	if (mpLevelUp == nullptr || mpBuffManager == nullptr)return 0;

	if (state == Status_Attack)
	{
		return mfNormalAttack + mpBuffManager->GetBuff(state)+mpLevelUp->GetAttack() + mfUpgradeAttack;
	}
	if (state == Status_Speed)
	{
		return speed_ + mpBuffManager->GetBuff(state)+mpLevelUp->GetSpeed() + mfUpgradeSpeed;
	}
	if (state == Status_Hp)
	{
		return max_hp_ + mpLevelUp->GetHp() + mfUpgradeMaxHp;
	}


}

void Player3D::CollDelete()
{
	if (mpAttachCollider != nullptr)
	{
		mpAttachCollider->SetDeleteFlag(true);
	}
	if (mpAttackJumpCollider != nullptr)
	{
		mpAttackJumpCollider->SetDeleteFlag(true);
	}
	if (mpAttackSlideCollider != nullptr)
	{
		mpAttackSlideCollider->SetDeleteFlag(true);
	}
	if ( mpSerchEnemyCollider!= nullptr)
	{
		mpSerchEnemyCollider->SetDeleteFlag(true);
	}
}


